python3 -c "
def find_yellow_pixels(file_path):
    with open(file_path, 'rb') as f:
        header = f.readline()
        line = f.readline().decode('utf-8')
        while line.startswith('#'):
            line = f.readline().decode('utf-8')
        width, height = map(int, line.strip().split())
        max_val = int(f.readline().strip())
        data = f.read()

        print('Scanning for yellow/greenish pixels (R > 150, G > 150, B < 100):')
        found = 0
        for y in range(550, 680):
            for x in range(50, 450):
                idx = (y * width + x) * 3
                if idx + 2 < len(data):
                    r, g, b = data[idx], data[idx+1], data[idx+2]
                    if r > 180 and g > 180 and b < 100:
                        print(f'x={x}, y={y}, RGB=({r},{g},{b})')
                        found += 1
                        if found > 50:
                            print('Too many matches, stopping search.')
                            return
        if found == 0:
            print('No bright yellow pixels found. Let s relax the threshold.')
            found_relaxed = 0
            for y in range(550, 680):
                for x in range(50, 450):
                    idx = (y * width + x) * 3
                    if idx + 2 < len(data):
                        r, g, b = data[idx], data[idx+1], data[idx+2]
                        # Relaxed yellow/orange/green: R > 120, G > 120, B < 120
                        if r > 120 and g > 120 and b < 120 and abs(r - g) < 40:
                            print(f'x={x}, y={y}, RGB=({r},{g},{b})')
                            found_relaxed += 1
                            if found_relaxed > 50:
                                print('Too many matches, stopping search.')
                                return
            if found_relaxed == 0:
                print('Still no yellow/green pixels found.')

find_yellow_pixels('work/frame_1000.ppm')
